new CheckerEnvKeys({
  get envKeys() {
    function readEnvKeys(fileName: string) {
      return {
        name: fileName,
        keys: Object.keys(parseEnv(fs.readFileSync(path.resolve(rootDir, fileName), 'utf8'))),
      };
    }

    return [readEnvKeys('.env'), readEnvKeys('.example.env')];
  },
}),
